create or replace function public.business_summary_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with l as(select count(*) locations,count(*) filter(where is_active) active_locations from locations where business_id=p_business_id),v as(select count(*) visits,count(distinct lv.user_id) unique_users from location_visits lv join locations l on l.id=lv.location_id where l.business_id=p_business_id and lv.occurred_at between p_start and p_end),c as(select count(*) check_ins,count(distinct ci.user_id) checkin_users from check_ins ci join locations l on l.id=ci.location_id where l.business_id=p_business_id and ci.checked_in_at between p_start and p_end),r as(select count(*) reviews,coalesce(avg(r.stars),0) average_rating from reviews r join locations l on l.id=r.location_id where l.business_id=p_business_id and r.created_at between p_start and p_end and r.status<>'hidden'),p as(select count(*) programs from partner_programs where business_id=p_business_id),e as(select count(*) events from business_events where business_id=p_business_id and(event_date is null or event_date between p_start::date and p_end::date)),pr as(select count(*) promotions from promotions where business_id=p_business_id) select jsonb_build_object('locations',(select locations from l),'active_locations',(select active_locations from l),'visits',(select visits from v),'unique_users',(select unique_users from v),'check_ins',(select check_ins from c),'checkin_users',(select checkin_users from c),'reviews',(select reviews from r),'average_rating',(select average_rating from r),'programs',(select programs from p),'events',(select events from e),'promotions',(select promotions from pr)); $$;
